// ── #467 — NE PLUS LEVER AVANT D'AVOIR RÉPONDU ───────────────────────────────
//
// Ce nœud levait sur chaque champ manquant. Or le webhook est en
// `responseMode: responseNode` : un nœud qui lève interrompt le workflow AVANT
// qu'un `respondToWebhook` soit atteint, et n8n ferme alors la requête avec
// **200 et un corps vide**. Pour l'appelant, indiscernable d'un succès sans
// résultat — et aucune trace de son côté.
//
// On rend donc un verdict que l'IF en aval sait router vers une vraie réponse 400.
// Les messages sont CONSERVÉS tels quels : un appelant qui les cherchait dans un
// journal les retrouve dans le corps de la réponse.
const body = ($input.first().json || {}).body || {};
const erreurs = [];
if (!body.guild_id) erreurs.push('guild_id is required');
if (!body.bot_id) erreurs.push('bot_id is required');
if (!body.backend_api_url) erreurs.push('backend_api_url is required');
if (!body.backend_service_token) erreurs.push('backend_service_token is required');
if (erreurs.length > 0) {
  return [{ json: { valid: false, errors: erreurs } }];
}

// Parse integer fields (default to 0 if null/undefined)
const memberCount = parseInt(body.member_count, 10) || 0;
const channelCount = parseInt(body.channel_count, 10) || 0;
const botCount = parseInt(body.bot_count, 10) || 0;

return [{ json: {
  valid: true,
  guild_id: body.guild_id,
  bot_id: body.bot_id,
  guild_name: body.guild_name || null,
  guild_icon: body.guild_icon || null,
  guild_description: body.guild_description || null,
  member_count: memberCount,
  channel_count: channelCount,
  bot_count: botCount,
  sync_source: body.sync_source || 'plugin',
  synced_by: body.synced_by || 'unknown',
  // ⚠️ Lus directement du corps : en réécrivant l'en-tête de ce nœud j'avais retiré
  // les deux `const` intermédiaires en laissant leurs références ici. `node --check`
  // ne voit pas une référence non résolue — seul le test l'a attrapée. En production
  // ça aurait levé, donc produit exactement le 200 vide que ce correctif supprime.
  backend_api_url: body.backend_api_url,
  backend_service_token: body.backend_service_token
} }];

// ── Parade #442/#467 — lire le STATUT RÉEL, jamais `|| 200` ──────────────────
//
// Le nœud HTTP porte désormais `fullResponse: true` + `neverError: true` : il émet
// { statusCode, body, headers } et ne lève plus sur un statut d'erreur. Reste le
// transport (délai, DNS, service éteint), où `onError: continueRegularOutput` fait
// émettre un objet d'erreur SANS statusCode — le statut réel n'existe alors que
// dans le message, sous la forme « 404 - {...} ».
function statutReel442(entree) {
  if (typeof entree.statusCode === 'number') return entree.statusCode;
  const brut = String((entree.error && entree.error.message) || entree.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  if (m) return parseInt(m[1], 10);
  return (entree.error || entree.code) ? 502 : 200;
}
// Le corps JSON de l'API, quand n8n l'a enfermé dans la chaîne du message d'erreur
// (doublement échappé). Sans ça le message reste `404 - "{\"detail\":…"`.
function corpsDansMessage442(entree) {
  const brut = String((entree.error && entree.error.message) || entree.message || '');
  const i = brut.indexOf('{'), j = brut.lastIndexOf('}');
  if (i < 0 || j <= i) return null;
  const bloc = brut.slice(i, j + 1);
  for (const essai of [bloc, bloc.replace(/\\"/g, '"').replace(/\\\\/g, '\\')]) {
    try { const o = JSON.parse(essai); if (o && typeof o === 'object') return o; } catch (e) { /* suivant */ }
  }
  return null;
}
// `detail` de FastAPI : parfois une chaîne, parfois une liste d'objets de validation.
function messageApi442(corps, defaut) {
  if (!corps) return defaut;
  const d = corps.detail;
  if (typeof d === 'string' && d) return d;
  if (Array.isArray(d) && d.length) {
    return d.map((e) => (e && e.msg) || JSON.stringify(e)).join(' ; ').slice(0, 300);
  }
  if (typeof corps.message === 'string' && corps.message) return corps.message;
  if (typeof corps.error === 'string' && corps.error) return corps.error;
  if (corps.error && typeof corps.error.message === 'string') return corps.error.message;
  return defaut;
}

// ── #467 — restituer l'échec au lieu de répondre 200 à vide ──────────────────
//
// `Sync to Backend` n'avait NI onError NI fullResponse. Un backend indisponible
// faisait donc lever le nœud, le workflow s'interrompait, et n8n fermait la requête
// avec 200 et rien dedans.
//
// ⚠️ Et le second défaut, sur le chemin NOMINAL : `Respond Success` calculait
// `success: $json.ok || $json.synced`. Sans `fullResponse`, `$json` était le corps
// du backend ; si celui-ci ne rendait ni `ok` ni `synced`, le champ valait
// `undefined` et **JSON.stringify le supprimait purement**. L'appelant recevait
// `{ guild_id, synced: true }` — sans `success`, et avec un `synced: true` écrit en
// dur qui affirmait la réussite quoi qu'il arrive.
const reponse = $input.first().json;
const demande = $('Validate Data').first().json;
const statut = statutReel442(reponse);
const corpsApi = (reponse.body !== undefined && reponse.body !== null)
  ? reponse.body
  : (corpsDansMessage442(reponse) || {});

if (statut >= 400 || reponse.error) {
  return [{ json: {
    success: false,
    guild_id: demande.guild_id || null,
    synced: false,
    error: {
      code: statut,
      message: messageApi442(corpsApi, 'synchronisation refusee par le backend'),
      status: 'SYNC_FAILED'
    },
    _trace: { service_response: corpsApi, http_status: statut }
  } }];
}

// Succès : `synced` reflète la réponse du backend, il n'est plus affirmé.
return [{ json: {
  success: true,
  guild_id: demande.guild_id || null,
  synced: true,
  http_status: statut
} }];
